    unverified.push('SOURCE_NOT_FOUND: "' + head + '" was not found at ' + url);
    continue;
  }
  const failure = String(entry.validation_error || '').trim();
  if (failure) {
    unverified.push('VALIDATION_FAILED: "' + head + '" (' + url + '): ' + failure);
    continue;
  }
  // A derived block is verified by the names it uses, not by its bytes: the server found
  // every one of them on a page this run read, so there is no excerpt to compare.
  if (String(entry.mode || 'quoted') === 'derived') { quoted += 1; continue; }
  if (norm(entry.excerpt) !== key) {
    unverified.push('UNQUOTED: "' + head + '" no longer matches ' + url);
    continue;
  }
  quoted += 1;
}
let sourceProblem = '';
if (fenced.length && !ledgerRead) {
  sourceProblem = 'SOURCES: sources.json could not be read'
    + (ledgerError ? ' (' + ledgerError + ')' : '')
    + '; a fenced block cannot be verified';
} else if (unverified.length) {
  sourceProblem = unverified.join('; ');
}
let problem = '';
if (sessionProblem) problem = sessionProblem;
else if (draftProblem) problem = draftProblem;
else if (!text) problem = 'EMPTY_DRAFT: the model returned no article body';
else if (!title) problem = 'EMPTY_TITLE: the draft has no H1 title';
else if (words > limit) problem = 'OVER_BUDGET: ' + words + ' words against a limit of ' + limit + ' (MAX_WORDS=' + max + ')';
else if (wrongMarkers.length) problem = 'MARKERS: ' + wrongMarkers.join(', ');
// Sourcing is the reviewer's: the ledger is data the audit reads, never a rejection here.

const describe = ledger
  .map((e) => '- ' + firstLine(e.block) + ' (' + (String(e.url || '').trim() || 'no url') + ')')
  .join('\n') || 'none';
return { json: {
  TITLE: title,
  TEXT: text,
  WORD_COUNT: words,
  MAX_WORDS: max,
  WORD_LIMIT: limit,
  SOURCES: ledgerRead ? sourcesJSON : '',
  SOURCES_TEXT: describe,
  SOURCES_NOTE: 'SOURCES: ' + quoted + ' quoted',
  FIDELITY: ledgerRead ? 'checked' : 'not run',
  PROBLEM: problem,
} };

// The request the article session receives: the entry's fields, nothing that reads like
// an instruction. The prompt, the shapes and the audience levels live in the writer
// adapter, so this graph cannot drift from the text the model is given. `session_id` is the
// row, so a retry continues the session directory and its fetched corpus instead of paying
// for every source again, and `attempt` tells the adapter this turn is a correction. The
// source hosts ride on the request because the pod cannot read the deployment values:
// `AgentRuntime.spec` carries no env, so the allowlist the proxy enforces arrives here.
const vars = $('main_trigger').first().json;
const config = $('set_workflow_vars').first().json;
const row = String(vars.ROW_NUMBER || '').trim();
if (!row) throw new Error('ROW_NUMBER is required: the session id is article-<row>');
const base = String($env.ARTICLE_WRITER_URL || '').replace(/\/+$/, '');
if (!base) throw new Error('ARTICLE_WRITER_URL is not set; the article session cannot be reached');
// One session per attempt. A retry used to continue the same Pi session, so its transcript
// grew to megabytes, compaction dropped the pages the ledger needs, and the turn took half
// an hour. A fresh session carries the previous draft and the reason instead.
// One session per row, for its whole life: the first draft and every later feedback round
// continue it, so the writer keeps the pages it read and the asks it already applied. A
// fresh session per attempt made a retry forget everything but the newest feedback.
const sessionId = ('article-' + row).replace(/[^A-Za-z0-9._-]/g, '').slice(0, 80);
const hosts = String(config.SOURCE_HOSTS || '').trim();
// On a retry this node is fed by `switch_article_check`'s retry output, so `$json`
// carries the reviewer's `explanation`; on the first attempt it carries the audiences.
const explanation = String(($json && $json.explanation) || '').trim();
const feedback = [
  String(vars.FEEDBACK || '').trim(),
  explanation ? 'The previous attempt failed the code check: ' + explanation : '',
].filter(Boolean).join('\n');
// A human retry runs in its own execution, so `parse_article` has not run yet; the draft
// the person read arrives in DRAFT_TEXT. Without it the retry re-drafts from the row and the
// newest feedback alone, which is how the 2026-11-09 retry replaced the whole walk-through
// with a provider how-to.
const previous = String(vars.DRAFT_TEXT || '').trim()
  || ($('parse_article').isExecuted ? String($('parse_article').last().json.TEXT || '') : '');
return [{ json: {
  SESSION_ID: sessionId,
  ATTEMPT: $runIndex + 1,
  ARTICLE_URL: base + '/v1/chat/completions',
  ARTIFACT_BASE: base + '/artifacts/' + sessionId,
  SOURCE_HOSTS: hosts,
  ARTICLE_BODY: JSON.stringify({
    session_id: sessionId,
    stream: false,
    source_hosts: hosts,
    attempt: $runIndex + 1,
    brief: {
      topic: String(vars.TOPIC || ''),
      description: String(vars.DESCRIPTION || ''),
      url: String(vars.URL || ''),
      max_words: Number(vars.MAX_WORDS) || 0,
      asset_types: String(vars.ASSET_TYPES || ''),
      audience: String(config.AUDIENCE || 'NONE'),
      extra_prompt: String(vars.EXTRA_PROMPT || ''),
      content: String(vars.CONTENT || ''),
      feedback,
      previous_draft: previous,
    },
  }),
} }];

// The aspect pass is the writer's turn too: this request names the task, the session and
// the draft, and the adapter renders each aspect prompt from its own registry. The graph
// holds no aspect id and no prompt text, so adding an aspect changes the image only.
const req = $('main_trigger').first().json;
const config = $('set_workflow_vars').first().json;
const row = String(req.ROW_NUMBER || '').trim();
if (!row) throw new Error('ROW_NUMBER is required: the session id is article-<row>');
const base = String($env.ARTICLE_WRITER_URL || '').replace(/\/+$/, '');
if (!base) throw new Error('ARTICLE_WRITER_URL is not set; the aspect turn cannot be reached');
const article = String(req.DRAFT_TEXT || '');
if (!article.trim()) throw new Error('DRAFT_TEXT is required for the aspect turn');
const sessionId = ('article-' + row).replace(/[^A-Za-z0-9._-]/g, '').slice(0, 80);
return [{ json: {
  ASPECTS_URL: base + '/v1/chat/completions',
  ASPECTS_BODY: JSON.stringify({
    task: 'aspects',
    session_id: sessionId,
    brief: {
      topic: String(req.TOPIC || ''),
      description: String(req.DESCRIPTION || ''),
      url: String(req.URL || ''),
      max_words: Number(req.MAX_WORDS) || 0,
      asset_types: String(req.ASSET_TYPES || ''),
      audience: String(config.AUDIENCE || 'NONE'),
      extra_prompt: String(req.EXTRA_PROMPT || ''),
      feedback: String(req.FEEDBACK || ''),
    },
    article: { title: String(req.DRAFT_TITLE || ''), text: article },
  }),
} }];

// The edit is the same session's next turn: the draft, the findings, and - on a retry -
// the objective problem the content writer's code re-check named. No prompt text and no
// model id ride on the request; the adapter owns both.
const req = $('main_trigger').first().json;
const config = $('set_workflow_vars').first().json;
const row = String(req.ROW_NUMBER || '').trim();
if (!row) throw new Error('ROW_NUMBER is required: the session id is article-<row>');
const base = String($env.ARTICLE_WRITER_URL || '').replace(/\/+$/, '');
if (!base) throw new Error('ARTICLE_WRITER_URL is not set; the improve turn cannot be reached');
const article = String(req.DRAFT_TEXT || '');
if (!article.trim()) throw new Error('DRAFT_TEXT is required for the improve turn');
const sessionId = ('article-' + row).replace(/[^A-Za-z0-9._-]/g, '').slice(0, 80);
return [{ json: {
  IMPROVE_URL: base + '/v1/chat/completions',
  IMPROVE_BODY: JSON.stringify({
    task: 'improve',
    session_id: sessionId,
    brief: {
      topic: String(req.TOPIC || ''),
      description: String(req.DESCRIPTION || ''),
      url: String(req.URL || ''),
      max_words: Number(req.MAX_WORDS) || 0,
      asset_types: String(req.ASSET_TYPES || ''),
      audience: String(config.AUDIENCE || 'NONE'),
      extra_prompt: String(req.EXTRA_PROMPT || ''),
      feedback: String(req.FEEDBACK || ''),
    },
    article: { title: String(req.DRAFT_TITLE || ''), text: article },
    findings: String(req.FINDINGS || ''),
    problem: String(req.PROBLEM || ''),
  }),
} }];

// The loop branches on the parser's verdict alone. The internal audit was a second model
// turn per attempt: it could reject a draft the code gate passed, and on 2026-11-09 it did
// exactly that on attempt 2. The human review is the judgement step; the code gate is the
// only automatic one. The audit task stays on the adapter for on-demand use.
const parsed = $('parse_article').item.json;
const problem = String(parsed.PROBLEM || '').trim();
return [{ json: { output: problem ? 'false' : 'true', explanation: problem } }];

// The audit is the writer's turn too, and it has tools: n8n sends the draft and the entry's
// fields, and the adapter's auditor reads the artifacts and the transcript to check a claim.
// and the adapter renders the gate prompt from its own files. One request carries both,
// so the verdict is about the draft this run parsed and no second copy of the prompt
// exists in the workflow.
const parsed = $('parse_article').first().json;
const req = $('main_trigger').first().json;
const config = $('set_workflow_vars').first().json;
const base = String($env.ARTICLE_WRITER_URL || '').replace(/\/+$/, '');
if (!base) throw new Error('ARTICLE_WRITER_URL is not set; the review turn cannot be reached');
const sessionId = ('article-' + String(req.ROW_NUMBER || '').trim()).replace(/[^A-Za-z0-9._-]/g, '').slice(0, 80);
return [{ json: {
  REVIEW_URL: base + '/v1/chat/completions',
  REVIEW_BODY: JSON.stringify({
    task: 'audit',
    session_id: sessionId,
    source_hosts: String(config.SOURCE_HOSTS || '').trim(),
    brief: {
      topic: String(req.TOPIC || ''),
      description: String(req.DESCRIPTION || ''),
      url: String(req.URL || ''),
      max_words: Number(req.MAX_WORDS) || 0,
      asset_types: String(req.ASSET_TYPES || ''),
      audience: String(config.AUDIENCE || 'NONE'),
      extra_prompt: String(req.EXTRA_PROMPT || ''),
      content: String(req.CONTENT || ''),
      feedback: String(req.FEEDBACK || '').trim(),
    },
    article: { title: String(parsed.TITLE || ''), text: String(parsed.TEXT || '') },
  }),
} }];

// The reviewer advises; it does not reject. Its findings ride with the draft to the human
// review, and a transport failure is a note like any other: a review that cannot answer
// must not cost a seven-minute draft (2026-11-09).
const res = $input.first().json;
const note = (value) => String(value == null ? '' : value).replace(/\s+/g, ' ').trim();
const transport = res.error ? note((res.error && res.error.message) || res.error) : '';
if (transport) return [{ json: { REVIEW_NOTE: 'REVIEW: ' + transport, REVIEW_FINDINGS: '' } }];
const status = Number(res.statusCode || res.status || 0);
const body = res.body && typeof res.body === 'object' ? res.body : {};
if (status >= 400) {
  const message = note((body.error && body.error.message) || body.error || body.message);
  return [{ json: { REVIEW_NOTE: 'REVIEW: HTTP ' + status + (message ? ': ' + message : ' the review turn failed'), REVIEW_FINDINGS: '' } }];
}
const review = body.review || {};
const findings = (Array.isArray(body.findings) ? body.findings : []).map((f) => note(f && f.text)).filter(Boolean).join(' ');
return [{ json: { REVIEW_NOTE: note(review.explanation || 'the reviewer returned no verdict'), REVIEW_FINDINGS: findings } }];
